{
 "description": "SSHSecretEngineRole is the Schema for the sshsecretengineroles API",
 "properties": {
  "spec": {
   "description": "SSHSecretEngineRoleSpec defines the desired state of SSHSecretEngineRole",
   "properties": {
    "algorithmSigner": {
     "description": "AlgorithmSigner algorithm to sign keys with (ssh-rsa, rsa-sha2-256, rsa-sha2-512, default).",
     "type": "string"
    },
    "allowBareDomains": {
     "description": "AllowBareDomains if true, host certs can use base domains from allowed_domains.",
     "type": "boolean"
    },
    "allowEmptyPrincipals": {
     "description": "AllowEmptyPrincipals allow signing certs with no valid principals.",
     "type": "boolean"
    },
    "allowHostCertificates": {
     "description": "AllowHostCertificates if true, certificates can be signed for host use.",
     "type": "boolean"
    },
    "allowSubdomains": {
     "description": "AllowSubdomains if true, host certs can use subdomains of allowed_domains.",
     "type": "boolean"
    },
    "allowUserCertificates": {
     "description": "AllowUserCertificates if true, certificates can be signed for user use.",
     "type": "boolean"
    },
    "allowUserKeyIDs": {
     "description": "AllowUserKeyIDs if true, users can override the key ID.",
     "type": "boolean"
    },
    "allowedCriticalOptions": {
     "description": "AllowedCriticalOptions comma-separated list of critical options.",
     "type": "string"
    },
    "allowedDomains": {
     "description": "AllowedDomains comma-separated domains for host certificates.",
     "type": "string"
    },
    "allowedDomainsTemplate": {
     "description": "AllowedDomainsTemplate if set, allowed_domains can contain identity templates.",
     "type": "boolean"
    },
    "allowedExtensions": {
     "description": "AllowedExtensions comma-separated list of extensions or \"*\".",
     "type": "string"
    },
    "allowedUserKeyLengths": {
     "additionalProperties": {
      "type": "integer"
     },
     "description": "AllowedUserKeyLengths map of ssh key types to allowed lengths.",
     "type": "object",
     "x-kubernetes-map-type": "granular"
    },
    "allowedUsers": {
     "description": "AllowedUsers comma-separated list or \"*\" for any user.",
     "type": "string"
    },
    "allowedUsersTemplate": {
     "description": "AllowedUsersTemplate if set, allowed_users can contain identity templates.",
     "type": "boolean"
    },
    "authentication": {
     "description": "Authentication is the kube auth configuration to be used to execute this request",
     "properties": {
      "namespace": {
       "description": "Namespace is the Vault namespace to be used in all the operations withing this connection/authentication. Only available in Vault Enterprise.",
       "type": "string"
      },
      "path": {
       "default": "kubernetes",
       "description": "Path is the path of the role used for this kube auth authentication. The operator will try to authenticate at {[namespace/]}auth/{spec.path}",
       "pattern": "^(?:/?[\\w;:@\u0026=\\$-\\.\\+]*)+/?",
       "type": "string"
      },
      "role": {
       "description": "Role the role to be used during authentication",
       "type": "string"
      },
      "serviceAccount": {
       "default": {
        "name": "default"
       },
       "description": "ServiceAccount is the service account used for the kube auth authentication",
       "properties": {
        "name": {
         "default": "",
         "description": "Name of the referent.\nThis field is effectively required, but due to backwards compatibility is\nallowed to be empty. Instances of this type with an empty value here are\nalmost certainly wrong.\nMore info: https://kubernetes.io/docs/concepts/overview/working-with-objects/names/#names",
         "type": "string"
        }
       },
       "type": "object",
       "x-kubernetes-map-type": "atomic"
      }
     },
     "required": [
      "path",
      "role",
      "serviceAccount"
     ],
     "type": "object"
    },
    "cidrList": {
     "description": "CIDRList comma-separated CIDR blocks. Required for OTP unless zero-address.",
     "type": "string"
    },
    "connection": {
     "description": "Connection represents the information needed to connect to Vault.",
     "properties": {
      "address": {
       "description": "Address Address of the Vault server expressed as a URL and port, for example: https://127.0.0.1:8200/",
       "type": "string"
      },
      "maxRetries": {
       "description": "MaxRetries Maximum number of retries when certain error codes are encountered. The default is 2, for three total attempts. Set this to 0 or less to disable retrying. Error codes that are retried are 412 (client consistency requirement not satisfied) and all 5xx except for 501 (not implemented).",
       "type": "integer"
      },
      "tLSConfig": {
       "properties": {
        "cacert": {
         "description": "Cacert Path to a PEM-encoded CA certificate file on the local disk. This file is used to verify the Vault server's SSL certificate. This environment variable takes precedence over a cert passed via the secret.",
         "type": "string"
        },
        "skipVerify": {
         "description": "SkipVerify Do not verify Vault's presented certificate before communicating with it. Setting this variable is not recommended and voids Vault's security model.",
         "type": "boolean"
        },
        "tlsSecret": {
         "description": "TLSSecret namespace-local secret containing the tls material for the connection. the expected keys for the secret are: ca bundle -\u003e \"ca.crt\", certificate -\u003e \"tls.crt\", key -\u003e \"tls.key\"",
         "properties": {
          "name": {
           "default": "",
           "description": "Name of the referent.\nThis field is effectively required, but due to backwards compatibility is\nallowed to be empty. Instances of this type with an empty value here are\nalmost certainly wrong.\nMore info: https://kubernetes.io/docs/concepts/overview/working-with-objects/names/#names",
           "type": "string"
          }
         },
         "type": "object",
         "x-kubernetes-map-type": "atomic"
        },
        "tlsServerName": {
         "description": "TLSServerName Name to use as the SNI host when connecting via TLS.",
         "type": "string"
        }
       },
       "type": "object"
      },
      "timeOut": {
       "description": "Timeout Timeout variable. The default value is 60s.",
       "type": "string"
      }
     },
     "required": [
      "address"
     ],
     "type": "object"
    },
    "defaultCriticalOptions": {
     "additionalProperties": {
      "type": "string"
     },
     "description": "DefaultCriticalOptions map of default critical options.",
     "type": "object",
     "x-kubernetes-map-type": "granular"
    },
    "defaultExtensions": {
     "additionalProperties": {
      "type": "string"
     },
     "description": "DefaultExtensions map of default extensions.",
     "type": "object",
     "x-kubernetes-map-type": "granular"
    },
    "defaultExtensionsTemplate": {
     "description": "DefaultExtensionsTemplate if set, default_extensions can contain identity templates.",
     "type": "boolean"
    },
    "defaultUser": {
     "description": "DefaultUser specifies the default username. Required for OTP type.",
     "type": "string"
    },
    "defaultUserTemplate": {
     "description": "DefaultUserTemplate if set, default_user can contain identity templates.",
     "type": "boolean"
    },
    "excludeCidrList": {
     "description": "ExcludeCIDRList comma-separated CIDR blocks to exclude.",
     "type": "string"
    },
    "keyIDFormat": {
     "description": "KeyIDFormat custom format for key id of signed certificate.",
     "type": "string"
    },
    "keyType": {
     "description": "KeyType specifies the type of credentials generated. Must be \"otp\" or \"ca\".",
     "enum": [
      "otp",
      "ca"
     ],
     "type": "string"
    },
    "maxTTL": {
     "description": "MaxTTL maximum TTL for credentials.",
     "type": "string"
    },
    "name": {
     "description": "The name of the object created in Vault. If this is specified it takes precedence over {metadata.name}",
     "pattern": "[a-z0-9]([-a-z0-9]*[a-z0-9])?",
     "type": "string"
    },
    "notBeforeDuration": {
     "description": "NotBeforeDuration duration to backdate ValidAfter property.",
     "type": "string"
    },
    "path": {
     "description": "Path at which to create the role.\nThe final path in Vault will be {[spec.authentication.namespace]}/{spec.path}/roles/{metadata.name}.",
     "pattern": "^(?:/?[\\w;:@\u0026=\\$-\\.\\+]*)+/?",
     "type": "string"
    },
    "port": {
     "default": 22,
     "description": "Port SSH port number.",
     "type": "integer"
    },
    "ttl": {
     "description": "TTL for credentials. Uses duration format strings.",
     "type": "string"
    }
   },
   "required": [
    "authentication",
    "keyType",
    "path"
   ],
   "type": "object"
  }
 },
 "title": "SSH Secret Engine Role",
 "type": "object"
}
